- \u8996\u70B9\u3084\u6642\u70B9\u3092\u5909\u3048\u308B\u306E\u306F\u3001\u610F\u56F3\u3057\u305F\u6F14\u51FA\u306E\u3068\u304D\u3060\u3051\u3002\u305D\u306E\u5834\u5408\u306F2\u756A\u3084Bridge\u306A\u3069\u30BB\u30AF\u30B7\u30E7\u30F3\u5358\u4F4D\u3067\u5207\u308A\u66FF\u3048\u3001
